import{_ as s,o as n,c as e,ai as l}from"./chunks/framework.Ba-VnP44.js";const o=JSON.parse('{"title":"08 代码测试","description":"","frontmatter":{},"headers":[],"relativePath":"ai/productivity/dev-spec/02-lifecycle/testing.md","filePath":"ai/productivity/dev-spec/02-lifecycle/testing.md"}'),i={name:"ai/productivity/dev-spec/02-lifecycle/testing.md"};function t(p,a,r,d,c,b){return n(),e("div",null,[...a[0]||(a[0]=[l(`<h1 id="_08-代码测试" tabindex="-1">08 代码测试 <a class="header-anchor" href="#_08-代码测试" aria-label="Permalink to “08 代码测试”">​</a></h1><blockquote><p>第二层 · 开发生命周期。解决「怎么证明功能真的能工作」——按层次补测试、按证据报结果，把「测过了」变成可核对的结论。</p></blockquote><h2 id="什么时候用" tabindex="-1">什么时候用 <a class="header-anchor" href="#什么时候用" aria-label="Permalink to “什么时候用”">​</a></h2><ul><li>功能开发、修复、重构完成后。</li><li>交付之前的必过环节。</li><li>L1 简单任务做局部检查，L2/L3 按任务级别补全测试。</li></ul><h2 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to “操作步骤”">​</a></h2><h3 id="测试分层" tabindex="-1">测试分层 <a class="header-anchor" href="#测试分层" aria-label="Permalink to “测试分层”">​</a></h3><table tabindex="0"><thead><tr><th>层次</th><th>测什么</th><th>什么时候补</th></tr></thead><tbody><tr><td>单元测试</td><td>单个函数、规则、边界条件</td><td>业务逻辑改动必补</td></tr><tr><td>集成测试</td><td>模块间协作、数据库、接口</td><td>涉及数据或跨模块时</td></tr><tr><td>端到端 / 冒烟</td><td>关键用户路径、接口联通</td><td>交付前、前端改动时</td></tr></tbody></table><p>按任务级别裁剪：简单任务跑局部检查即可；普通功能补单测 + 相关集成；复杂功能补全部分层 + 回归。</p><h3 id="补测试的重点" tabindex="-1">补测试的重点 <a class="header-anchor" href="#补测试的重点" aria-label="Permalink to “补测试的重点”">​</a></h3><ul><li>覆盖关键路径<strong>和失败路径</strong>，不只测正常情况。</li><li>覆盖边界：空值、零值、重复、越权、状态不允许。</li><li>断言要精确，能确实区分对错，不写永远为真的断言。</li><li>不为了让测试通过而放宽断言、删除用例、改测试数据掩盖问题。</li></ul><h3 id="执行顺序" tabindex="-1">执行顺序 <a class="header-anchor" href="#执行顺序" aria-label="Permalink to “执行顺序”">​</a></h3><p>先快后慢：编译/类型检查 → 出问题的那一个测试 → 相关模块 → 接口冒烟 → 全量测试。一上来跑全量，慢且失败信息不聚焦。</p><h3 id="四态报告" tabindex="-1">四态报告 <a class="header-anchor" href="#四态报告" aria-label="Permalink to “四态报告”">​</a></h3><p>结果必须分清四种状态，不能把没跑的写成通过：</p><table tabindex="0"><thead><tr><th>状态</th><th>怎么写</th></tr></thead><tbody><tr><td>已验证</td><td>「单测 X 通过，输出见日志」</td></tr><tr><td>未验证</td><td>「测试库不可用，未跑集成测试；已用本地库跑单测替代」</td></tr><tr><td>受限</td><td>「生产配置只读，未做线上验证」</td></tr><tr><td>不适用</td><td>「未涉及前端改动，无需浏览器验证」</td></tr></tbody></table><p><strong>没有输出的「已测试」等于没测试。</strong> 详细规范见第三层 <a href="/my-vitepress-site/ai/productivity/dev-spec/03-quality/test-verification.html">测试与验证规范</a>。</p><h2 id="可复制提示词" tabindex="-1">可复制提示词 <a class="header-anchor" href="#可复制提示词" aria-label="Permalink to “可复制提示词”">​</a></h2><details><summary><strong>补单元测试</strong></summary><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请为下面这段代码补单元测试。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>代码：&lt;粘贴代码或文件&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要求：</span></span>
<span class="line"><span>1. 覆盖正常路径、关键边界（空值、零值、越界、重复）和失败路径。</span></span>
<span class="line"><span>2. 断言要精确，能区分对错，不写恒真断言。</span></span>
<span class="line"><span>3. 测试名说清「什么情况下应该怎样」。</span></span>
<span class="line"><span>4. 不修改被测试的业务代码。</span></span>
<span class="line"><span>5. 如果有难以测试的地方（依赖外部服务、静态调用），说明需要怎么隔离。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>输出测试代码 + 每个用例覆盖的场景说明。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div></details><details><summary><strong>补测试与回归清单</strong></summary><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>本次改动：&lt;描述&gt;</span></span>
<span class="line"><span>请基于改动内容，产出一份测试与回归清单，本轮只输出清单，不执行。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请列出：</span></span>
<span class="line"><span>1. 必跑项：编译/类型检查、相关单测、接口冒烟（写具体命令）。</span></span>
<span class="line"><span>2. 回归项：哪些原有功能必须保持不变，各自怎么验证。</span></span>
<span class="line"><span>3. 边界项：这次改动涉及的边界条件（空值、权限、状态、并发）。</span></span>
<span class="line"><span>4. 无法自动化的项：需要人工核对的页面行为或数据状态。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>每项给「检查点 → 预期结果 → 验证方式」。</span></span>
<span class="line"><span>最后标出哪些属于「漏了就出事」的检查，建议固化为脚本（见 Hooks / Scripts）。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div></details><h2 id="验收要点" tabindex="-1">验收要点 <a class="header-anchor" href="#验收要点" aria-label="Permalink to “验收要点”">​</a></h2><ul><li>[ ] 测试覆盖关键路径和失败路径，断言精确。</li><li>[ ] 按先快后慢顺序执行，有命令输出证据。</li><li>[ ] 结果按四态区分，没跑的没写成通过。</li><li>[ ] 回归项覆盖了「原有功能不变」。</li><li>[ ] 没有通过放宽断言或删用例让测试变绿。</li></ul><p>测试通过进入 <a href="/my-vitepress-site/ai/productivity/dev-spec/02-lifecycle/delivery.html">09 交付与复用</a>。</p>`,22)])])}const u=s(i,[["render",t]]);export{o as __pageData,u as default};
